import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"功能模块总览","description":"灵萌 V2 全部功能模块一览：基础能力、社区内容、消息交易、本地生活、AI 与基础设施，可按区域按需开启。","frontmatter":{"title":"功能模块总览","description":"灵萌 V2 全部功能模块一览：基础能力、社区内容、消息交易、本地生活、AI 与基础设施，可按区域按需开启。"},"headers":[],"relativePath":"guide/modules.md","filePath":"guide/modules.md","lastUpdated":1785020677000}'),o={name:"guide/modules.md"};function s(h,t,i,c,n,l){return e(),r("div",null,[...t[0]||(t[0]=[a(`<p>灵萌采用<strong>模块化单体</strong>架构：后台共有 <strong>30 个业务模块</strong>代码包，对外按 <strong>36 项能力</strong>组合交付。您无需一次性全开——按校区/社区的实际需求，在管理后台或授权配置中<strong>按需启用</strong>即可。</p><div class="tip custom-block"><p class="custom-block-title">本文档不含价格</p><p>此处仅说明各模块「做什么、依赖什么、去哪配置」。采购与授权事宜请联系官方渠道。</p></div><h2 id="模块怎么运作" tabindex="-1">模块怎么运作 <a class="header-anchor" href="#模块怎么运作" aria-label="Permalink to &quot;模块怎么运作&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[平台基础能力] --&gt; B[区域配置]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[客户端入口]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; D[管理后台菜单]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; E[用户可见功能]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; F[运营配置能力]</span></span></code></pre></div><ol><li><strong>基础内置</strong>：用户、评论、通知、订单、审核等底座随系统提供，保障社区能跑起来。</li><li><strong>可选增值</strong>：私信、外卖、AI、优惠券等按授权与区域开关单独启用。</li><li><strong>区域隔离</strong>：同一套系统可服务多个校区/社区，各区域 UI、规则、功能开关可独立配置。</li></ol><hr><h2 id="一、基础内置" tabindex="-1">一、基础内置 <a class="header-anchor" href="#一、基础内置" aria-label="Permalink to &quot;一、基础内置&quot;">​</a></h2><p>随系统提供，构成社区运行的最小闭环。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>基础社交</td><td>用户账号与资料、通用评论、站内通知、统一订单与审核底座</td><td>—</td><td><a href="/config/user-rules">用户规则</a></td></tr><tr><td>圈子体系</td><td>圈子/成员/权限、笔记与话题、发现流</td><td>基础社交</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>支付能力</td><td>微信/支付宝收款、统一支付单、余额账本与资金流水</td><td>—</td><td><a href="/features/payment">支付与提现</a></td></tr><tr><td>本地更新推送</td><td>私有化实例版本检查、安装与推送（适合自建部署）</td><td>—</td><td><a href="/config/system-settings">系统配置总览</a></td></tr></tbody></table><hr><h2 id="二、社区与内容" tabindex="-1">二、社区与内容 <a class="header-anchor" href="#二、社区与内容" aria-label="Permalink to &quot;二、社区与内容&quot;">​</a></h2><p>丰富 UGC 玩法，提升社区活跃度。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>热帖精帖计算</td><td>按区域规则自动打热帖/精帖标签</td><td>建议开启热度算法</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>话题 PK</td><td>话题下正反方投票、状态自动流转</td><td>圈子体系</td><td><a href="/features/vote-selection">投票与评选</a></td></tr><tr><td>话题活动</td><td>打卡、挂载抽奖等话题运营玩法</td><td>圈子体系</td><td><a href="/features/vote-selection">投票与评选</a></td></tr><tr><td>投票</td><td>笔记内联投票，可配置匿名</td><td>圈子体系</td><td><a href="/features/vote-selection">投票与评选</a></td></tr><tr><td>匿名身份</td><td>匿名身份池，发笔记/评论时可切换</td><td>圈子体系</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>热度算法</td><td>定时重算笔记热度，支持热度排序</td><td>圈子体系</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>评分体系</td><td>多目标评分、搜索索引联动</td><td>圈子体系</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr><tr><td>评选活动</td><td>圈子评选、作品投稿与投票</td><td>圈子体系</td><td><a href="/features/vote-selection">投票与评选</a></td></tr><tr><td>视频笔记沉浸页</td><td>视频笔记全屏沉浸播放</td><td>圈子体系</td><td><a href="/features/circle-note">圈子与笔记</a></td></tr></tbody></table><hr><h2 id="三、消息与连接" tabindex="-1">三、消息与连接 <a class="header-anchor" href="#三、消息与连接" aria-label="Permalink to &quot;三、消息与连接&quot;">​</a></h2><p>让用户留在站内、实时互动。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>私信群聊</td><td>WebSocket 即时通信，私聊/独立群/圈子群</td><td>—</td><td><a href="/features/message">私信与群聊</a></td></tr><tr><td>群红包</td><td>群聊内发红包、领取与过期退回</td><td>私信群聊、支付</td><td><a href="/features/message">私信与群聊</a></td></tr><tr><td>聊天转账</td><td>一对一转账，过期自动退回</td><td>私信群聊、支付</td><td><a href="/features/message">私信与群聊</a></td></tr><tr><td>微信模板消息</td><td>公众号/小程序模板变量与通知通道</td><td>微信配置</td><td><a href="/features/notification">通知与推送</a></td></tr><tr><td>官方机器人</td><td>站内助手账号与对话</td><td>—</td><td><a href="/features/bot-notify">官方机器人</a></td></tr><tr><td>机器人推送</td><td>对外事件流（HTTP/WS），对接企微/钉钉脚本</td><td>—</td><td><a href="/features/open-stream">机器人推送</a></td></tr></tbody></table><hr><h2 id="四、交易与营销" tabindex="-1">四、交易与营销 <a class="header-anchor" href="#四、交易与营销" aria-label="Permalink to &quot;四、交易与营销&quot;">​</a></h2><p>从内容社区延伸到变现闭环。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>二手闲置</td><td>闲置发布、联系与交易</td><td>支付、圈子</td><td><a href="/features/idle">闲置交易</a></td></tr><tr><td>推广员体系</td><td>推广员申请、绑定与佣金结算</td><td>—</td><td><a href="/features/promotion">推广员体系</a></td></tr><tr><td>抽奖</td><td>抽奖活动、参与与自动开奖</td><td>—</td><td><a href="/features/lottery">抽奖活动</a></td></tr><tr><td>营销券中心</td><td>领券/购券/核销/ROI/审批全链路</td><td>支付</td><td><a href="/features/coupon">优惠券与营销</a></td></tr><tr><td>微信/支付宝自动提现</td><td>提现申请、审核、打款与对账</td><td>支付</td><td><a href="/features/finance">财务流水与提现</a></td></tr><tr><td>拼团套餐</td><td>团购套餐、开团/参团/购买</td><td>支付</td><td><a href="/features/payment">支付与提现</a></td></tr><tr><td>会员体系</td><td>会员套餐、购买/订阅与权益发放</td><td>支付</td><td><a href="/features/payment">支付与提现</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">自定义服务收单</p><p>帮取帮送、预约登记、代办申请等场景，可通过 <a href="/features/ui-editor/components-form">UI 编辑器 · 服务表单</a> 拖拽搭建，无需单独开发页面。</p></div><hr><h2 id="五、本地生活" tabindex="-1">五、本地生活 <a class="header-anchor" href="#五、本地生活" aria-label="Permalink to &quot;五、本地生活&quot;">​</a></h2><p>外卖、跑腿等地域性生活服务。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>外卖</td><td>商家/菜品/购物车/订单/评价全链路</td><td>支付</td><td><a href="/features/takeaway">外卖</a></td></tr><tr><td>骑手配送</td><td>骑手申请、派单/转单、轨迹与结算</td><td>外卖</td><td><a href="/features/rider">骑手</a></td></tr><tr><td>跑腿服务</td><td>可配置跑腿模板、报价与下单</td><td>支付</td><td><a href="/features/errand">跑腿</a></td></tr></tbody></table><hr><h2 id="六、智能、界面与基础设施" tabindex="-1">六、智能、界面与基础设施 <a class="header-anchor" href="#六、智能、界面与基础设施" aria-label="Permalink to &quot;六、智能、界面与基础设施&quot;">​</a></h2><p>提升运营效率与系统能力上限。</p><table tabindex="0"><thead><tr><th>模块</th><th>能力说明</th><th>依赖</th><th>配置文档</th></tr></thead><tbody><tr><td>AI 中台</td><td>多模型网关、异步任务、各业务 AI 入口</td><td>—</td><td><a href="/features/ai">AI 中台</a></td></tr><tr><td>智能评论</td><td>智能回复、评论摘要、自动发评</td><td>AI 中台</td><td><a href="/features/ai-comment">智能评论</a></td></tr><tr><td>MCP 管理工具</td><td>MCP Key/策略/插件市场与调用审计</td><td>—</td><td><a href="/features/ai">AI 中台</a></td></tr><tr><td>UI 管理配置</td><td>区域页面可视化编排、TabBar 与组件</td><td>—</td><td><a href="/features/ui-editor/">UI 编辑器</a></td></tr><tr><td>推荐引擎</td><td>行为埋点、协同/向量召回与相关推荐</td><td>圈子体系</td><td><a href="/features/search">搜索与推荐</a></td></tr><tr><td>Meilisearch 搜索</td><td>全文/智能搜索、索引重建与健康探测</td><td>—</td><td><a href="/features/search">搜索与推荐</a></td></tr><tr><td>云存储</td><td>COS/OSS/七牛等对象存储与 CDN 前缀</td><td>—</td><td><a href="/features/storage">文件存储</a></td></tr><tr><td>水印功能</td><td>图片/视频/封面自动叠加水印</td><td>—</td><td><a href="/features/storage">文件存储</a></td></tr><tr><td>数据管理</td><td>超级管理员表元数据、检索与批量改数</td><td>超级管理员</td><td><a href="/config/system-settings">系统配置总览</a></td></tr></tbody></table><hr><h2 id="七、后端业务模块索引-30" tabindex="-1">七、后端业务模块索引（30） <a class="header-anchor" href="#七、后端业务模块索引-30" aria-label="Permalink to &quot;七、后端业务模块索引（30）&quot;">​</a></h2><p>以下为代码层面的 <strong>30 个业务模块包</strong>，与上表「能力项」多对一或多对多对应，供技术同学快速定位。</p><table tabindex="0"><thead><tr><th>模块标识</th><th>中文名称</th><th>主要职责</th></tr></thead><tbody><tr><td><code>user</code></td><td>用户与账号</td><td>注册登录、资料、等级、认证、余额与提现</td></tr><tr><td><code>system</code></td><td>系统与配置</td><td>全局/区域配置、PageConfig、文件、授权与运维</td></tr><tr><td><code>circle</code></td><td>圈子与笔记</td><td>圈子、笔记、话题、发现流、匿名与热度</td></tr><tr><td><code>comment</code></td><td>通用评论</td><td>跨业务统一评论能力</td></tr><tr><td><code>message</code></td><td>即时消息</td><td>WebSocket IM、会话、红包与转账</td></tr><tr><td><code>notification</code></td><td>通知推送</td><td>站内信、短信、微信订阅/模板消息</td></tr><tr><td><code>order</code></td><td>统一订单</td><td>跨业务订单创建、状态与支付回调</td></tr><tr><td><code>payment</code></td><td>支付</td><td>微信/支付宝 JSAPI、支付单与退款</td></tr><tr><td><code>fund</code></td><td>资金账本</td><td>余额变更、流水与对账</td></tr><tr><td><code>coupon</code></td><td>优惠券</td><td>领券、核销、ROI 与营销规则</td></tr><tr><td><code>membership</code></td><td>会员</td><td>套餐、订阅与权益</td></tr><tr><td><code>groupbuy</code></td><td>团购</td><td>拼团开团/参团/购买</td></tr><tr><td><code>lottery</code></td><td>抽奖</td><td>活动状态机、参与与开奖</td></tr><tr><td><code>promotion</code></td><td>推广员</td><td>绑定、佣金与区域推广配置</td></tr><tr><td><code>idle</code></td><td>闲置交易</td><td>闲置发布、联系与订单</td></tr><tr><td><code>selection</code></td><td>评选活动</td><td>投稿、投票与榜单</td></tr><tr><td><code>review</code></td><td>统一审核</td><td>跨模块内容审核与落地</td></tr><tr><td><code>search</code></td><td>搜索</td><td>Meilisearch 索引与检索</td></tr><tr><td><code>recommend</code></td><td>推荐</td><td>埋点、召回与排序</td></tr><tr><td><code>takeaway</code></td><td>外卖</td><td>商家、菜品、购物车与订单</td></tr><tr><td><code>rider</code></td><td>骑手</td><td>配送派单、轨迹与结算</td></tr><tr><td><code>errand</code></td><td>跑腿</td><td>模板、报价与履约</td></tr><tr><td><code>store</code></td><td>门店</td><td>门店信息与业务挂载</td></tr><tr><td><code>aiapp</code></td><td>AI 中台</td><td>Provider 网关、场景路由与配额</td></tr><tr><td><code>llmchat</code></td><td>LLM 对话</td><td>多轮对话与会话管理</td></tr><tr><td><code>mcp</code></td><td>MCP 管理</td><td>Key、策略、插件市场</td></tr><tr><td><code>openstream</code></td><td>开放事件流</td><td>对外 HTTP/WS 事件推送</td></tr><tr><td><code>link</code></td><td>内容链接</td><td>跨模块 content_links 卡片</td></tr><tr><td><code>linkhub</code></td><td>模块联动</td><td>订单、账本、AI 上下文等跨模块编排</td></tr><tr><td><code>eventoutbox</code></td><td>事件出站</td><td>可靠事件投递与异步消费</td></tr></tbody></table><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>首次部署：<a href="/guide/quick-start">快速部署</a> → <a href="/guide/setup-wizard">初始化向导</a></li><li>找菜单：<a href="/guide/admin-menu-map">后台菜单地图</a> → <a href="/guide/admin-access">进入管理后台</a></li><li>看开通情况：<a href="/config/my-modules">我的模块</a> → <a href="/config/admin-permissions">账号权限</a></li><li>按模块开启：<a href="/features/wechat">功能开启</a> 各专题文档</li><li>多区域运营：<a href="/config/region">区域管理</a> → <a href="/config/user-rules">用户规则</a></li><li>上线前检查：<a href="/ops/checklist">上线检查清单</a></li></ul>`,37)])])}const p=d(o,[["render",s]]);export{u as __pageData,p as default};
